<template>
  <div class="profiles-container">
    <!-- 页面头部 -->
    <div class="page-header">
      <el-page-header :icon="ArrowLeft" @back="goBack">
        <template #content>
          <span class="page-title">用户管理</span>
        </template>
      </el-page-header>
    </div>

    <!-- 主内容卡片 -->
    <div class="content-card">
      <!-- 卡片头部：搜索和操作 -->
      <div class="card-header">
        <div class="search-area">
          <el-input
            v-model="searchText"
            placeholder="搜索姓名/学号"
            :prefix-icon="Search"
            class="feishu-input"
            clearable
            @keyup.enter="handleSearch"
            @clear="handleSearch"
          />
        </div>
        <el-button type="primary" class="feishu-btn" @click="handleAdd">
          <el-icon><Plus /></el-icon>
          新增用户
        </el-button>
      </div>

      <!-- 数据表格 -->
      <div class="table-wrapper">
        <el-table :data="profiles" stripe class="feishu-table">
          <el-table-column prop="username" label="用户名" width="120" />
          <el-table-column prop="student_id" label="学号/工号" width="120" />
          <el-table-column prop="name" label="姓名" width="120" />
          <el-table-column prop="role" label="角色" width="100">
            <template #default="{ row }">
              <span class="role-tag">{{ row.role }}</span>
            </template>
          </el-table-column>
          <el-table-column prop="email" label="邮箱" min-width="200" />
          <el-table-column prop="phone" label="电话" width="150" />
          <el-table-column label="操作" fixed="right" width="160">
            <template #default="{ row }">
              <el-button size="small" link type="primary" @click="handleEdit(row)">编辑</el-button>
              <el-button size="small" link type="danger" @click="handleDelete(row)">删除</el-button>
            </template>
          </el-table-column>
        </el-table>
      </div>
    </div>

    <!-- 用户表单对话框 -->
    <el-dialog
      v-model="dialogVisible"
      :title="isEdit ? '编辑用户' : '新增用户'"
      width="520px"
      class="feishu-dialog"
      destroy-on-close
    >
      <el-form :model="form" label-width="100px" ref="formRef" :rules="rules" class="feishu-form">
        <el-form-item label="用户名" prop="username">
          <el-input v-model="form.username" placeholder="请输入用户名" />
        </el-form-item>
        <el-form-item label="密码" prop="password">
          <el-input v-model="form.password" type="password" placeholder="留空则不修改密码" show-password />
        </el-form-item>
        <el-form-item label="姓名" prop="name">
          <el-input v-model="form.name" placeholder="请输入姓名" />
        </el-form-item>
        <el-form-item label="学号/工号" prop="student_id">
          <el-input v-model="form.student_id" placeholder="请输入学号/工号" />
        </el-form-item>
        <el-form-item label="角色" prop="role">
          <el-select v-model="form.role" placeholder="请选择角色" style="width: 100%">
            <el-option
              v-for="role in meta.roles"
              :key="role.code"
              :label="role.label"
              :value="role.code"
            />
          </el-select>
        </el-form-item>
        <el-form-item label="邮箱" prop="email">
          <el-input v-model="form.email" placeholder="请输入邮箱" />
        </el-form-item>
        <el-form-item label="电话" prop="phone">
          <el-input v-model="form.phone" placeholder="请输入电话" />
        </el-form-item>
      </el-form>
      <template #footer>
        <span class="dialog-footer">
          <el-button class="feishu-btn-secondary" @click="dialogVisible = false">取消</el-button>
          <el-button type="primary" class="feishu-btn" @click="submitForm">确定</el-button>
        </span>
      </template>
    </el-dialog>
  </div>
</template>

<script setup>
import { ref, onMounted, reactive } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { ArrowLeft, Search, Plus } from '@element-plus/icons-vue'
import api from '@/api'

const router = useRouter()
const profiles = ref([])
const searchText = ref('')
const dialogVisible = ref(false)
const isEdit = ref(false)
const formRef = ref(null)
const meta = ref({ roles: [] })

const form = reactive({
  id: null,
  username: '',
  password: '',
  name: '',
  student_id: '',
  role: '硕士生',
  email: '',
  phone: ''
})

const rules = {
  username: [{ required: true, message: '请输入用户名', trigger: 'blur' }],
  name: [{ required: true, message: '请输入姓名', trigger: 'blur' }],
  student_id: [{ required: true, message: '请输入学号/工号', trigger: 'blur' }],
  role: [{ required: true, message: '请选择角色', trigger: 'change' }],
  email: [
    { required: true, message: '请输入邮箱', trigger: 'blur' },
    { type: 'email', message: '请输入正确的邮箱格式', trigger: 'blur' }
  ]
}

const fetchProfiles = async () => {
  try {
    const params = {}
    if (searchText.value) {
      params.search = searchText.value
    }
    const response = await api.getProfiles(params)
    let data = response.data
    profiles.value = data.results || data || []
  } catch (error) {
    ElMessage.error('获取用户列表失败')
    profiles.value = []
  }
}

const goBack = () => {
  router.push('/')
}

const handleSearch = () => {
  fetchProfiles()
}

const handleAdd = () => {
  isEdit.value = false
  Object.assign(form, {
    id: null,
    username: '',
    password: '',
    name: '',
    student_id: '',
    role: '硕士生',
    email: '',
    phone: ''
  })
  dialogVisible.value = true
}

const handleEdit = (row) => {
  isEdit.value = true
  Object.assign(form, {
    id: row.id,
    username: row.username || row.user?.username || '',
    password: '',
    name: row.name,
    student_id: row.student_id,
    role: row.role,
    email: row.email,
    phone: row.phone
  })
  dialogVisible.value = true
}

const handleDelete = (row) => {
  ElMessageBox.confirm(`确定要删除用户 "${row.name}" 吗？`, '提示', {
    confirmButtonText: '确定',
    cancelButtonText: '取消',
    type: 'warning'
  }).then(async () => {
    try {
      await api.deleteProfile(row.id)
      ElMessage.success('删除成功')
      fetchProfiles()
    } catch (error) {
      ElMessage.error('删除失败')
    }
  })
}

const submitForm = async () => {
  if (!formRef.value) return
  await formRef.value.validate(async (valid) => {
    if (valid) {
      try {
        const postData = { ...form }
        postData.write_username = form.username
        delete postData.username
        if (isEdit.value && !postData.password) {
          delete postData.password
        }

        if (isEdit.value) {
          await api.updateProfile(form.id, postData)
          ElMessage.success('修改成功')
        } else {
          await api.createProfile(postData)
          ElMessage.success('新增成功')
        }
        dialogVisible.value = false
        fetchProfiles()
      } catch (error) {
        const details = error?.response?.data
        const msg = details ? JSON.stringify(details) : (isEdit.value ? '修改失败' : '新增失败')
        ElMessage.error(msg)
      }
    }
  })
}

onMounted(() => {
  api.getMeta().then(r => { meta.value = r.data || {} }).catch(() => {})
  fetchProfiles()
})
</script>

